package com.benbenyu.btquicklaunch;
import android.os.*;import android.bluetooth.*;
/** Narrow, root-only bridge: connect the one paired car keyboard, no arbitrary commands. */
public final class RootHidConnect {
 public static void main(String[] args){Object am=null;IBinder token=new Binder();try{am=Class.forName("android.app.ActivityManager").getMethod("getService").invoke(null);Class<?> manager=Class.forName("android.app.IActivityManager");Object holder=manager.getMethod("getContentProviderExternal",String.class,int.class,IBinder.class,String.class).invoke(am,"com.benbenyu.btquicklaunch.hid",0,token,"SimpleHomeHid");if(holder==null)throw new Exception("Provider unavailable");Object provider=holder.getClass().getField("provider").get(holder);Bundle result=(Bundle)Class.forName("android.content.IContentProvider").getMethod("call",String.class,String.class,String.class,String.class,String.class,Bundle.class).invoke(provider,null,null,"com.benbenyu.btquicklaunch.hid","binder",null,null);AppLog.init(new java.io.File("/data/data/com.benbenyu.btquicklaunch/files/logs"),result.getInt("uid"));IBinder hid=result.getBinder("hid");if(hid==null||!"android.bluetooth.IBluetoothHidHost".equals(hid.getInterfaceDescriptor()))throw new Exception("HID binder unavailable");BluetoothDevice device=BluetoothAdapter.getDefaultAdapter().getRemoteDevice(DeviceConfig.KEYBOARD_MAC);if(device.getBondState()!=BluetoothDevice.BOND_BONDED)throw new Exception("Keyboard not paired");Parcel data=Parcel.obtain(),reply=Parcel.obtain();try{data.writeInterfaceToken("android.bluetooth.IBluetoothHidHost");data.writeInt(1);device.writeToParcel(data,0);if(!hid.transact(1,data,reply,0))throw new Exception("Unsupported HID transaction");reply.readException();int accepted=reply.readInt();AppLog.write("ROOT_HID_CONNECT accepted="+accepted,null);if(accepted==0)throw new Exception("Connect rejected");}finally{data.recycle();reply.recycle();}}catch(Throwable e){AppLog.write("ROOT_HID_CONNECT_FAILED",e);e.printStackTrace();System.exit(2);}finally{if(am!=null)try{Class.forName("android.app.IActivityManager").getMethod("removeContentProviderExternalAsUser",String.class,IBinder.class,int.class).invoke(am,"com.benbenyu.btquicklaunch.hid",token,0);}catch(Exception ignored){}}}
}
